begin;

-- --------------------------------------------------------- prerequisites ----
do $$
begin
  if to_regclass('kofi.lots') is null or to_regclass('kofi.applied_migrations') is null
     or to_regprocedure('kofi.js_iso(timestamptz)') is null or to_regprocedure('kofi.try_uuid(text)') is null then
